&lt;table border=0 cellpadding=0 cellspacing=0 border=0 cellpadding=0 cellspacing=0&gt;&lt;tr&gt;&lt;td style="font-size: 15px; line-height: 1.48em; padding: 0px 15px;"&gt;
&lt;p&gt;&lt;span style="font-size: 1.2em;"&gt;🧰&lt;/span&gt; &lt;span style="text-transform: uppercase;    font-weight: 600; font-size: 1.4em;"&gt;Tools, Code &amp;amp; Resources&lt;/span&gt;&lt;/p&gt;
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;table border=0 cellpadding=0 cellspacing=0 border=0 cellpadding=0 cellspacing=0&gt;&lt;tr&gt;&lt;td style="font-size: 15px; line-height: 1.48em;"&gt;
  &lt;a href="https://frontendfoc.us/link/190429/rss" style=" color: #D94306;"&gt;&lt;img src="https://res.cloudinary.com/cpress/image/upload/w_1280,e_sharpen:60,q_auto/v1789557313/crpjqoc9ssmdanb1ijub.png" width="640" style="    line-height: 100%;      "&gt;&lt;/a&gt;
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;

&lt;table border=0 cellpadding=0 cellspacing=0 border=0 cellpadding=0 cellspacing=0&gt;&lt;tr&gt;&lt;td style="font-size: 15px; line-height: 1.48em; padding: 0px 18px;"&gt;

  &lt;p&gt;&lt;span style="font-weight: 400 !important; font-size: 1.3em !important; color: #000;"&gt;&lt;a href="https://frontendfoc.us/link/190429/rss" title="neat-annotations.syabro.com" style=" color: #D94306;"&gt;Neat Annotations: Elegant Hand-Drawn Annotations with CSS&lt;/a&gt;&lt;/span&gt; — A lovely way to add some flourish to your content - think hand-drawn arrows and labels, all in CSS. Scroll down on the demo page to get the idea, or &lt;a href="https://frontendfoc.us/link/190430/rss" style=" color: #D94306;"&gt;see the repo&lt;/a&gt;.&lt;/p&gt;
  &lt;p&gt;Maxim Syabro &lt;/p&gt;
